import{z as A,x as p,o as n,c as d,q as s,j as i,D as o,d as r,s as t,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"Work-span 与 fork-join","description":"","frontmatter":{"title":"Work-span 与 fork-join","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/work-span-model.md","filePath":"cs/work-span-model.md","lastUpdated":1791413859000}'),B={name:"cs/work-span-model.md"};function P(m,a,f,k,u,S){const l=p("Mermaid");return n(),d("div",null,[a[2]||(a[2]=s('<h1 id="work-span-与-fork-join" tabindex="-1">Work-span 与 fork-join <a class="header-anchor" href="#work-span-与-fork-join" aria-label="Permalink to &quot;Work-span 与 fork-join&quot;">​</a></h1><div class="epigraph"><p>工作 $W$ 是总运算，跨度 $S$ 是依赖最长链；贪心调度 $P$ 核上时间 $\\le W/P+S$。</p><footer>—— 据 Brent, The Parallel Evaluation of General Arithmetic Expressions, 1974；Cilk / Blumofe–Leiserson 工作窃取整理</footer></div><p>上一课<a href="/cs/pram-prefix-sum">PRAM 前缀和</a>已给出 \\(W=O(n)\\)、\\(S=O(\\log n)\\)；缺口是把这两个量变成真正的成本模型——不再假设 \\(n\\) 台处理器齐步走。fork-join 给出表达：<code>spawn</code> 子任务、<code>sync</code> 等待。本课不重写前缀树；后课排序网络是比较器电路，Cilk 工作窃取的期望界在本课收拢。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把计算看成 DAG：结点是运算，边是依赖；\\(W\\) 是结点数，\\(S\\) 是最长路。Brent 调度定律给出上界 \\(T_P\\le W/P+S\\)：\\(P\\) 个核要么在干活（贡献 \\(W/P\\)），要么在等关键链走完（贡献 \\(S\\)）。工作窃取调度把这个界变成可实现的：闲核从别的核双端队列另一端偷子任务，空间与时间都高概率近最优。</p><p>缺口是调度定律，不是再写前缀代码。</p><h3 id="不是-倍加速永远成立" tabindex="-1">不是 \\(P\\) 倍加速永远成立 <a class="header-anchor" href="#不是-倍加速永远成立" aria-label="Permalink to &quot;不是 $P$ 倍加速永远成立&quot;">​</a></h3><p>加速比有硬顶：\\(T_P\\ge S\\) 是关键链决定的下界，\\(T_P\\ge W/P\\) 是工作量决定的下界，Amdahl 的串行段只是 \\(S\\) 的直观说法。报告并行结果要同时给 \\(W\\)、\\(S\\) 与实测数据，不要只报「并行了」。</p><p><span class="marginnote">直觉类比：跨度就是「流水线上最慢的那条链」——雇一万个人也快不过炖汤的那口锅。\\(T_P\\ge S\\) 说的正是：任何调度都短不过最长依赖链，加处理器买不来这段等待。</span></p><p><span class="marginnote">Brent 1974。Blumofe–Leiserson Cilk。后课排序网络跨度是比较器层数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把分治写成 fork-join：<code>fork</code> 两半、<code>join</code> 合并、合并做线性工作；随即读出 \\(W(n)=2W(n/2)+O(n)\\) 与 \\(S(n)=S(n/2)+O(n)\\)——归并排序在这个模型里天然并行，加速比 \\(T_1/T_P\\) 的上界是 \\(\\min(P,\\,W/S)\\)。</p>',12)),(n(),i(E,null,{default:o(()=>[t(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DAG%5B%22%E8%AE%A1%E7%AE%97%20DAG%22%5D%20--%3E%20W%5B%22%E5%B7%A5%E4%BD%9C%20W%22%5D%0A%20%20DAG%20--%3E%20S%5B%22%E8%B7%A8%E5%BA%A6%20S%22%5D%0A%20%20W%20--%3E%20TP%5B%22T_P%20%E2%89%A4%20W%2FP%20%2B%20S%22%5D%0A%20%20S%20--%3E%20TP%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"任务粒度要足够粗：递归切到单叶任务只剩几十条指令时，调度开销反过来吃掉并行收益。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：\\(W=10^8\\) 条指令、\\(S=10^4\\) 层、\\(P=100\\) 核时，\\(T_P\\) 的上界是 \\(10^8/100+10^4=1.01\\times 10^6\\)——先按工作量均摊，再加关键链，两项相加就是界的形状。两项差一个数量级时，谁大谁就是瓶颈。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"机制在调度器一侧：任意时刻的就绪任务数给出当前可并行度，贪心调度总能让 \\(P\\) 个核不闲，除非就绪任务不够——这正是 \\(W/P+S\\) 两项的来源。工作窃取把双端队列当任务池：本核从底端压弹自己的任务，偷取从顶端拿，两端无锁竞争，局部性也保住了。与 PRAM 对照：PRAM 假定全局同步与访存冲突规则，work-span 直接挂在语言运行时上，更接近真实机器。",-1)),a[7]||(a[7]=e("p",null,"窃取在队列两端如何分工：",-1)),(n(),i(E,null,{default:o(()=>[t(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20DQ%5B%22%E6%A0%B8%201%20%E7%9A%84%E5%8F%8C%E7%AB%AF%E9%98%9F%E5%88%97%22%5D%20--%3E%7C%22%E8%87%AA%E5%B7%B1%20push%20%E4%B8%8E%20pop%22%7C%20BOT%5B%22%E5%BA%95%E7%AB%AF%EF%BC%9A%E6%9C%80%E6%96%B0%E5%AD%90%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20BOT%20--%3E%20RUN1%5B%22%E6%A0%B8%201%20%E5%B0%B1%E5%9C%B0%E6%89%A7%E8%A1%8C%22%5D%0A%20%20IDLE%5B%22%E6%A0%B8%202%20%E9%97%B2%E4%BA%86%22%5D%20--%3E%7C%22%E4%BB%8E%E9%A1%B6%E7%AB%AF%E5%81%B7%22%7C%20TOP%5B%22%E9%A1%B6%E7%AB%AF%EF%BC%9A%E6%9C%80%E8%80%81%E5%AD%90%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20TOP%20--%3E%20RUN2%5B%22%E6%A0%B8%202%20%E6%89%A7%E8%A1%8C%E8%A2%AB%E5%81%B7%E7%9A%84%E4%B8%80%E5%8D%8A%22%5D%0A%20%20RUN1%20--%3E%20JOIN%5B%22join%20%E6%B1%87%E5%90%88%22%5D%0A%20%20RUN2%20--%3E%20JOIN%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=s('<p><span class="marginnote">为什么重要：从顶端偷、从底端拿，让最热的最新任务留在本核，被偷走的总是最冷最老的整棵子树——一次偷取搬一大块，摊薄了窃取的同步开销，还顺手保住了缓存局部性。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 GPU 的 occupancy 账，不写共享内存锁——fork-join 假设任务间无数据竞争。后课默认：并行算法报 \\(W\\) 与 \\(S\\)。下一课排序网络。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(T_P\\le W/P+S\\)；\\(T_P\\ge\\max(W/P,S)\\)。</li><li>fork-join 表达分治 DAG。</li><li>工作窃取近最优调度。</li><li>出处：Brent, 1974；Cilk 工作窃取。</li></ul>',5))])}const h=A(B,[["render",P]]);export{c as __pageData,h as default};
